-- The audit pages list the vault's token issues, revokes and sign-outs (T164): with 0.15's log, none writes 0.14's `token.create`, `token.revoke` or `sign_out` entry, and its change is the record (D147), which the app reads as it reads the sign-ins (0042). Two indexes over those changes alone, every member's and one's, ordered as the sign-ins' (`at`, then the number), so that a page reads as many as it shows, and a page that hides them counts no more than its stretch holds, however many other changes the log holds. Each is known by how its payload starts, an issue's or a revoke's, and by the record it holds: an `issue` object, or a reason of `revoke` or `sign_out` (`RECORDS` in @coffre/db's change-records.ts, which the reads repeat). Additive: the previous release reads nothing here.
--> statement-breakpoint
CREATE INDEX "log_changes_issue_revoke_idx" ON "log_changes" USING btree ("at","number") WHERE ((strpos("log_changes"."payload", '{"caller":"') = 1 AND strpos("log_changes"."payload", '"issue":{"by":"') > 0) OR (strpos("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND strpos("log_changes"."payload", '"reason":"revoke"') > 0) OR (strpos("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND strpos("log_changes"."payload", '"reason":"sign_out"') > 0));--> statement-breakpoint
CREATE INDEX "log_changes_issue_revoke_actor_idx" ON "log_changes" USING btree ("actor","at","number") WHERE ((strpos("log_changes"."payload", '{"caller":"') = 1 AND strpos("log_changes"."payload", '"issue":{"by":"') > 0) OR (strpos("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND strpos("log_changes"."payload", '"reason":"revoke"') > 0) OR (strpos("log_changes"."payload", '{"op":"credential.revoke",') = 1 AND strpos("log_changes"."payload", '"reason":"sign_out"') > 0));
